def backfill_last_shift(apps, schema_editor):
    """Turn each person's last known punch times into a shift record."""

    StaffProfile = apps.get_model("store", "StaffProfile")
    ShiftRecord = apps.get_model("store", "ShiftRecord")

    for profile in StaffProfile.objects.filter(
        role__in=["employee", "delivery"], punched_in_at__isnull=False
    ):
        if profile.is_punched_in:
            ShiftRecord.objects.create(
                user_id=profile.user_id, role=profile.role, punched_in_at=profile.punched_in_at
            )
        elif profile.punched_out_at and profile.punched_out_at > profile.punched_in_at:
            ShiftRecord.objects.create(
                user_id=profile.user_id,
                role=profile.role,
                punched_in_at=profile.punched_in_at,
                punched_out_at=profile.punched_out_at,
            )


